/**
 * A showcase of dishes: each card is one link to the dish page (picture, badge, name, weight, summary, price and
 * an arrow). No cart here. Axes: cols (3, 4), ratio (4/3, 1/1), tone.
 */
import { type ReactNode } from "react";
import { Badge, Grid, Group, Inline, Link, Stack } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { fmtMoney, tpl, urlOf } from "../utils";
import type { Dish, FoodLabels } from "./dish-showcase.types";

export type DishShowcaseProps = {
  id: string;
  title: string;
  lead?: string;
  dishes: Dish[];
  empty?: string;
  labels: FoodLabels;
  cols?: "3" | "4";
  ratio?: "4/3" | "1/1";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function DishShowcase({
  id,
  title,
  lead = "",
  dishes,
  empty = "",
  labels,
  cols = "3",
  ratio = "4/3",
  tone = "default",
  landmarkLabel,
}: DishShowcaseProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} landmarkLabel={landmarkLabel}>
      {((dishes?.length ?? 0) === 0) ? (
        <EmptyState icon="star" title={empty} />
      ) : (
        <Grid cols={(((cols as string) === "4") ? "2-4" : "1-3")} className="gap-8" data-slot="items">
          {(dishes ?? []).map((d) => (
            <Link key={d.id}
              href={urlOf((d.href ?? tpl("#/dish/{0}", d.id)))}
              variant="block"
              className="group flex-col items-stretch gap-4"
              data-slot="item"
            >
              <MediaFrame alt={d.name} ratio={ratio} />
              <Stack gap="2">
                {d.badge ? (
                  <Badge variant="secondary" size="sm" className="w-fit">
                    {d.badge}
                  </Badge>
                ) : null}
                <Group gap="2" align="baseline" justify="between">
                  <Inline className="text-lg font-semibold">
                    {d.name}
                  </Inline>
                  <Inline className="text-sm text-muted-foreground">
                    {d.weight}
                  </Inline>
                </Group>
                <Inline className="text-sm font-normal text-muted-foreground">
                  {d.summary}
                </Inline>
                <Group gap="2" align="center" justify="between">
                  <Inline className="text-base font-bold">
                    {fmtMoney(d.price, d.currency)}
                  </Inline>
                  <Inline className="flex items-center gap-2 text-sm text-primary">
                    {labels.open}
                    <LucideIcon name="arrow-right" size={16} />
                  </Inline>
                </Group>
              </Stack>
            </Link>
          ))}
        </Grid>
      )}
    </SectionFrame>
  );
}

